package io.coolbox.math;
import io.coolbox.internal.ErrorBuffer;
/** Python {@code math.solve_heat_equation} and {@code math.solve_stochastic_heat_equation}. */
public final class HeatEquation {private HeatEquation(){}public static double[] solve(double[] initial,long[] shape,int dimensions,double alpha,double dx,double dt,int steps){return solveHeatEquation(initial,shape,dimensions,alpha,dx,dt,steps,1,1);}public static double[] solveHeatEquation(double[] initial,long[] shape,int dimensions,double alpha,double dx,double dt,int steps,double dy,double dz){return solve(initial,shape,dimensions,alpha,0,dx,dy,dz,dt,steps,0,false);}public static double[] solveStochasticHeatEquation(double[] initial,long[] shape,int dimensions,double alpha,double sigma,double dx,double dy,double dz,double dt,int steps,int seed){return solve(initial,shape,dimensions,alpha,sigma,dx,dy,dz,dt,steps,seed,true);}private static double[] solve(double[] in,long[] s,int d,double a,double sig,double dx,double dy,double dz,double dt,int steps,int seed,boolean stochastic){if(s.length!=3)throw new IllegalArgumentException("shape must contain three dimensions");long n=s[0]*s[1]*s[2];if(n!=in.length)throw new IllegalArgumentException("shape does not match initial values");double[] out=new double[in.length];ErrorBuffer e=new ErrorBuffer();e.check(MathNative.INSTANCE.coolbox_math_heat(d,stochastic?1:0,in,s[0],s[1],s[2],a,sig,dx,dy,dz,dt,steps,seed,out,e.pointer(),e.capacity()));return out;}}
